module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

	reg [31:0] register [1:31]; 				// r1 - r31

	// TODO: implement — register read ports and write logic
	// Read ports should return 0 for register x0, and support write-forwarding
	// Write logic should update register[Wt_addr] with Wt_data when L_S is asserted
	assign rdata_A = 32'b0;
	assign rdata_B = 32'b0;

	integer i;
	always @(posedge clk or posedge rst)
      begin
		if (rst) begin
		    for (i=1; i<32; i=i+1) begin
		    	register[i] <= 0;
			end
		end
	end

    assign Debug_regs = (Debug_addr == 0) ? 0 : register[Debug_addr];               //TEST

endmodule




